options.onOperationButtonClick:
const todoId = row['id']
this.getFormRef().globalDsv.id = todoId
if(buttonName==='edit')
{
  this.getFormRef().executeDataSource('detail').then(res=&gt;{
    this.getFormRef().showDialog('AddOrUpdateDialog',res,{editFlag:'edit'});
  })
}
else if(buttonName==='delete')
{
  this.$confirm('此操作将永久删除该条信息, 是否继续?', '提示',{
    confirmButtonText: '确定',
      cancelButtonText: '取消',
      type: 'warning'
  }).then(() =&gt; {
      this.getFormRef().executeDataSource('delete').then(res=&gt;{
      this.$message.success("删除成功！")
      let dt=this.getFormRef().getWidgetRef('dtBusiness',false);
      dt.loadDataFromDS({});
      }).catch(error=&gt;{
        this.$message.success("删除失败！")
      })
    }).catch(() =&gt; {
      this.$message({
        type: 'info',
        message: '已取消删除'
      });
    });
}
else{}

